const contacts = $json.data.contacts;
const skipped = $json.data.skipped || [];
const noteSubmissionId = $('Claim Note Submission').item.json.id;
return contacts.map((c) => ({ json: { contact: c, noteSubmissionId: noteSubmissionId, skipped: skipped } }));

const contact = $('Prepare Contacts For Posting').item.json.contact;
const label = [contact.firstName, contact.lastName].filter(Boolean).join(' ') || 'unnamed contact';
return { json: { created: true, label: label } };

const contact = $('Prepare Contacts For Posting').item.json.contact;
const label = [contact.firstName, contact.lastName].filter(Boolean).join(' ') || 'unnamed contact';
return { json: { created: false, label: label, error: $json.error || 'unknown error' } };

const items = $input.all();
const created = items.filter((i) => i.json.created).length;
const failures = items.filter((i) => !i.json.created).map((i) => i.json.label + ': ' + i.json.error);
// Every item was stamped with the same noteSubmissionId/skipped in
// Prepare Contacts For Posting (before the fan-out), so any item works.
const noteSubmissionId = $('Prepare Contacts For Posting').first().json.noteSubmissionId;
const skipped = $('Prepare Contacts For Posting').first().json.skipped;
const allFailed = failures.length > 0 && created === 0;
return [{ json: {
  status: allFailed ? 'failed' : 'completed',
  error: failures.length > 0 ? failures.join('; ') : null,
  skipped: skipped,
  noteSubmissionId: noteSubmissionId,
} }];
